insert into public.glossary_terms (term_es, term_en, term_pt, definition_es, definition_en, definition_pt, visibility, status, published_at, content_updated_at) values
  ('1080i 59.94', '1080i 59.94', '1080i 59.94', 'Formato de vídeo de alta definición de los Juegos: 1080 líneas, entrelazado, 59,94 campos por segundo (SDR, 16:9).', 'The Games'' high-definition video format: 1080 lines, interlaced, 59.94 fields per second (SDR, 16:9).', 'Formato de vídeo de alta definição dos Jogos: 1080 linhas, entrelaçado, 59,94 campos por segundo (SDR, 16:9).', 'all', 'published', now(), now()),
  ('Ceremonia de himnos', 'Anthem ceremony', 'Cerimônia de hinos', 'Ceremonia previa al inicio de la competencia en los deportes de conjunto. Los deportes individuales no la tienen.', 'The ceremony before the start of competition in team sports. Individual sports do not have one.', 'Cerimônia antes do início da competição nos esportes coletivos. Os esportes individuais não têm.', 'all', 'published', now(), now()),
  ('BVM adjunto', 'Assistant BVM', 'BVM assistente', 'Apoya al Broadcast Venue Manager en una sede.', 'Supports the Broadcast Venue Manager at a venue.', 'Apoia o Broadcast Venue Manager em um local de competição.', 'all', 'published', now(), now()),
  ('B-roll', 'B-roll', 'B-roll', 'Imágenes generales no ligadas a una acción concreta, que se usan para montar una nota.', 'General footage that is not tied to a specific action, used to cut into a story.', 'Imagens gerais não ligadas a uma ação específica, usadas para montar uma matéria.', 'all', 'published', now(), now()),
  ('BIO (Broadcast Information Office)', 'BIO (Broadcast Information Office)', 'BIO (Broadcast Information Office)', 'El punto de contacto de los RHB en cada sede. Preséntese allí al llegar y para todo lo que necesite en la sede.', 'The RHBs'' point of contact at each venue. Report here on arrival and for anything you need on site.', 'O ponto de contato dos RHB em cada local. Apresente-se ali ao chegar e para tudo o que precisar no local.', 'all', 'published', now(), now()),
  ('BVM (Broadcast Venue Manager)', 'BVM (Broadcast Venue Manager)', 'BVM (Broadcast Venue Manager)', 'El responsable de la operación de broadcast en una sede. Hay un BVM por sede y representa a Booking.', 'The head of the broadcast operation at a venue. There is one BVM per venue, who also represents Booking.', 'O responsável pela operação de broadcast em um local. Há um BVM por local, que também representa o Booking.', 'all', 'published', now(), now()),
  ('CCU (Commentary control unit)', 'CCU (Commentary control unit)', 'CCU (Commentary control unit)', 'El equipo de una posición de comentarios que gestiona el audio de los comentarios y las comunicaciones.', 'The equipment at a commentary position that handles commentary audio and communications.', 'O equipamento de uma posição de comentário que gerencia o áudio dos comentários e as comunicações.', 'all', 'published', now(), now()),
  ('CIS (Commentator Information System)', 'CIS (Commentator Information System)', 'CIS (Commentator Information System)', 'Servicio de resultados e información para comentaristas, con datos de la competencia en directo.', 'A results and information service for commentators, with live data on the competition.', 'Serviço de resultados e informações para comentaristas, com dados da competição ao vivo.', 'all', 'published', now(), now()),
  ('Señal limpia (clean feed)', 'Clean feed', 'Sinal limpo (clean feed)', 'Una señal sin gráficos en pantalla.', 'A signal without on-screen graphics.', 'Um sinal sem gráficos na tela.', 'all', 'published', now(), now()),
  ('Com-cam', 'Com-cam', 'Com-cam', 'Cámara controlada a distancia en una posición de comentarios.', 'A remote-controlled camera at a commentary position.', 'Câmera controlada remotamente em uma posição de comentário.', 'all', 'published', now(), now()),
  ('Posición de comentarios', 'Commentary position', 'Posição de comentário', 'Pupitre en la sede equipado para los comentaristas.', 'A desk at the venue equipped for commentators.', 'Mesa no local equipada para os comentaristas.', 'all', 'published', now(), now()),
  ('Señal sucia (dirty feed)', 'Dirty feed', 'Sinal sujo (dirty feed)', 'La señal internacional con los gráficos. La señal limpia es la misma señal sin ellos.', 'The international signal including the graphics. The clean feed is the same signal without them.', 'O sinal internacional com os gráficos. O sinal limpo é o mesmo sinal sem eles.', 'all', 'published', now(), now()),
  ('ENG (Electronic news gathering)', 'ENG (Electronic news gathering)', 'ENG (Electronic news gathering)', 'Equipo de cámara móvil que capta material informativo, normalmente fuera del plan de cámaras fijo.', 'A mobile camera crew gathering news material, usually working outside the fixed camera plan.', 'Equipe de câmera móvel que capta material jornalístico, normalmente fora do plano de câmeras fixo.', 'all', 'published', now(), now()),
  ('FOP (Field of play)', 'FOP (Field of play)', 'FOP (Field of play)', 'El área de competencia de cada deporte.', 'The competition area of each sport.', 'A área de competição de cada esporte.', 'all', 'published', now(), now()),
  ('Front of house / Back of house', 'Front of house / Back of house', 'Front of house / Back of house', 'Las zonas de una sede abiertas al público (front of house) y las zonas de trabajo no públicas (back of house).', 'The areas of a venue open to the public (front of house) and the non-public working areas (back of house).', 'As áreas de um local abertas ao público (front of house) e as áreas de trabalho não públicas (back of house).', 'all', 'published', now(), now()),
  ('GFX (Gráficos)', 'GFX (Graphics)', 'GFX (Grafismo)', 'Gráficos en pantalla, como resultados, nombres y cronometraje.', 'On-screen graphics such as results, names and timing.', 'Grafismo na tela, como resultados, nomes e cronometragem.', 'all', 'published', now(), now()),
  ('HB (Host Broadcaster)', 'HB (Host Broadcaster)', 'HB (Host Broadcaster)', 'El broadcaster responsable de producir y distribuir la señal internacional de los Juegos. En Lima 2027, Imagina.', 'The broadcaster responsible for producing and distributing the international signal of the Games. At Lima 2027, Imagina.', 'A emissora responsável por produzir e distribuir o sinal internacional dos Jogos. Em Lima 2027, a Imagina.', 'all', 'published', now(), now()),
  ('Evento de alta demanda', 'High-demand event', 'Evento de alta demanda', 'Sesión en la que las solicitudes de facilidades superan lo que la sede puede acoger con seguridad. Se aplica el procedimiento habitual de arbitraje.', 'A session where the requests for facilities exceed what the venue can safely hold. The usual arbitration procedure applies.', 'Sessão em que os pedidos de facilidades superam o que o local comporta com segurança. Aplica-se o procedimento habitual de arbitragem.', 'all', 'published', now(), now()),
  ('HSSM (High-speed slow motion)', 'HSSM (High-speed slow motion)', 'HSSM (High-speed slow motion)', 'Cámara de muy alta velocidad de imagen para repeticiones en cámara ultralenta.', 'A very high frame-rate camera used for extreme slow-motion replays.', 'Câmera de altíssima taxa de quadros para replays em câmera ultralenta.', 'all', 'published', now(), now()),
  ('IBC', 'IBC', 'IBC', 'International Broadcast Centre: el centro donde trabajan los broadcasters durante los Juegos.', 'International Broadcast Centre: the hub where broadcasters work during the Games.', 'International Broadcast Centre: o centro onde as emissoras trabalham durante os Jogos.', 'all', 'published', now(), now()),
  ('Señal internacional', 'International feed', 'Sinal internacional', 'La transmisión en vivo de una sesión, del run-up al run-out, íntegra de la secuencia animada de apertura a la de cierre.', 'The live broadcast of a session, from the run-up to the run-out, complete from the opening to the closing animation.', 'A transmissão ao vivo de uma sessão, do run-up ao run-out, completa da vinheta de abertura à de encerramento.', 'all', 'published', now(), now()),
  ('Sonido internacional', 'International sound', 'Som internacional', 'El sonido ambiente de la sede, sin comentarios, que acompaña a la señal internacional.', 'The ambient sound of the venue, without commentary, delivered with the international feed.', 'O som ambiente do local, sem comentários, que acompanha o sinal internacional.', 'all', 'published', now(), now()),
  ('ISO dump', 'ISO dump', 'ISO dump', 'Entrega de las señales de cámaras aisladas grabadas, después de una sesión.', 'Delivery of recorded isolated camera feeds after a session.', 'Entrega das câmeras isoladas gravadas, depois de uma sessão.', 'all', 'published', now(), now()),
  ('Señal ISO', 'ISO feed', 'Sinal ISO', 'Señal de una cámara aislada, grabada o distribuida aparte de la salida de programa.', 'An isolated camera signal recorded or distributed separately from the programme output.', 'Sinal de uma câmera isolada, gravado ou distribuído à parte da saída de programa.', 'all', 'published', now(), now()),
  ('Sesión de medallas', 'Medal session', 'Sessão de medalhas', 'Sesión en la que se entregan medallas. Todos los días de finales y medallas se transmiten en vivo.', 'A session in which medals are awarded. All finals and medal days are broadcast live.', 'Sessão em que se entregam medalhas. Todos os dias de finais e medalhas são transmitidos ao vivo.', 'all', 'published', now(), now()),
  ('Zona mixta', 'Mixed zone', 'Zona mista', 'Zona donde los medios pueden entrevistar a los atletas después de la competencia.', 'Area where media can interview athletes after competition.', 'Área onde a mídia pode entrevistar os atletas depois da competição.', 'all', 'published', now(), now()),
  ('Señal multilateral', 'Multilateral feed', 'Sinal multilateral', 'La señal internacional producida por el Host Broadcaster y ofrecida a todos los Right Holders.', 'The international signal produced by the Host Broadcaster and offered to all Right Holders.', 'O sinal internacional produzido pelo Host Broadcaster e oferecido a todos os Right Holders.', 'all', 'published', now(), now()),
  ('Medio sin derechos (non-rights holder)', 'Non-rights holder', 'Veículo sem direitos (non-rights holder)', 'Organización de medios que no tiene derechos de transmisión. No puede cubrir la competencia en vivo.', 'A media organisation that does not hold broadcast rights. It may not cover the competition live.', 'Organização de mídia que não tem direitos de transmissão. Não pode cobrir a competição ao vivo.', 'all', 'published', now(), now()),
  ('Unidad móvil (OB van)', 'OB van', 'Unidade móvel (OB van)', 'Vehículo de exteriores con el equipamiento de producción de una sede.', 'Outside Broadcast vehicle with the production equipment for a venue.', 'Veículo externo com o equipamento de produção de um local.', 'all', 'published', now(), now()),
  ('Asientos de observador', 'Observer seats', 'Assentos de observador', 'Asientos junto a las posiciones de comentarios que los RHB pueden usar para trabajar. No son una posición de operación broadcast.', 'Seats next to the commentary positions that RHBs may use for working purposes. They are not a broadcast operating position.', 'Assentos junto às posições de comentário que os RHB podem usar para trabalhar. Não são uma posição de operação de broadcast.', 'all', 'published', now(), now()),
  ('Comentario off-tube', 'Off-tube commentary', 'Comentário off-tube', 'Comentario hecho frente a una pantalla, sin vista directa del campo de juego.', 'Commentary made from a screen, without a direct view of the field of play.', 'Comentário feito a partir de uma tela, sem vista direta do campo de jogo.', 'all', 'published', now(), now()),
  ('Señal posterior (post-match feed)', 'Post-match feed', 'Sinal posterior (post-match feed)', 'La señal después de la señal internacional, con ISO dumps, resúmenes de la sesión y compilaciones.', 'The feed after the international feed, with ISO dumps, session summaries and compilations.', 'O sinal depois do sinal internacional, com ISO dumps, resumos da sessão e compilações.', 'all', 'published', now(), now()),
  ('Cámara POV', 'POV camera', 'Câmera POV', 'Cámara pequeña colocada para que el espectador sienta que está dentro de la acción, por ejemplo una minicámara.', 'A small camera placed so that viewers feel they are inside the action, for example a mini or pin camera.', 'Câmera pequena colocada para o espectador sentir que está dentro da ação, por exemplo uma minicâmera.', 'all', 'published', now(), now()),
  ('Señal previa (pre-match feed)', 'Pre-match feed', 'Sinal prévio (pre-match feed)', 'La señal antes de la señal internacional. Lleva imágenes de la sede y los stand-ups reservados por los RHB.', 'The feed before the international feed. It carries venue pictures and the stand-ups reserved by RHBs.', 'O sinal antes do sinal internacional. Traz imagens do local e os stand-ups reservados pelos RHB.', 'all', 'published', now(), now()),
  ('RHB (Rights Holding Broadcaster)', 'RHB (Rights Holding Broadcaster)', 'RHB (Rights Holding Broadcaster)', 'Broadcaster que tiene los derechos de transmisión de los Juegos y recibe la señal internacional.', 'A broadcaster that holds the broadcast rights of the Games and receives the international signal.', 'Emissora que detém os direitos de transmissão dos Jogos e recebe o sinal internacional.', 'all', 'published', now(), now()),
  ('Run-out', 'Run-out', 'Run-out', 'La secuencia programada después del final de una sesión, con los resultados y la animación de cierre.', 'The programmed sequence after the end of a session, including the results and the closing animation.', 'A sequência programada depois do fim de uma sessão, com os resultados e a vinheta de encerramento.', 'all', 'published', now(), now()),
  ('Run-up', 'Run-up', 'Run-up', 'La secuencia programada de planos, gráficos y animaciones antes del inicio de la competencia.', 'The programmed sequence of shots, graphics and animations before the start of competition.', 'A sequência programada de planos, grafismo e vinhetas antes do início da competição.', 'all', 'published', now(), now()),
  ('SNG (Satellite news gathering)', 'SNG (Satellite news gathering)', 'SNG (Satellite news gathering)', 'Vehículo con equipo de enlace satelital que se usa para enviar una señal desde la sede.', 'A vehicle with satellite uplink equipment used to send a signal from the venue.', 'Veículo com equipamento de uplink via satélite usado para enviar um sinal do local.', 'all', 'published', now(), now()),
  ('SSM (Super slow motion)', 'SSM (Super slow motion)', 'SSM (Super slow motion)', 'Cámara de alta velocidad para repeticiones en cámara lenta.', 'A high-speed camera used for slow-motion replays.', 'Câmera de alta velocidade para replays em câmera lenta.', 'all', 'published', now(), now()),
  ('Señal de prueba (test feed)', 'Test feed', 'Sinal de teste (test feed)', 'La prueba técnica de la señal antes de una sesión.', 'The technical test of the signal before a session.', 'O teste técnico do sinal antes de uma sessão.', 'all', 'published', now(), now()),
  ('Timecode', 'Timecode', 'Timecode', 'Referencia de tiempo incluida en una señal de vídeo.', 'Time reference embedded in a video signal.', 'Referência de tempo incluída em um sinal de vídeo.', 'all', 'published', now(), now()),
  ('Unilateral', 'Unilateral', 'Unilateral', 'Cobertura producida por un solo Right Holder para su propia audiencia.', 'Coverage produced by a single Right Holder for its own audience.', 'Cobertura produzida por um único Right Holder para o seu próprio público.', 'all', 'published', now(), now()),
  ('UPS (Uninterruptible power supply)', 'UPS (Uninterruptible power supply)', 'UPS (Uninterruptible power supply)', 'Respaldo de baterías que mantiene el equipo funcionando si falla la red eléctrica.', 'A battery back-up that keeps equipment running if the mains power fails.', 'Backup de baterias que mantém o equipamento funcionando se a rede elétrica falhar.', 'all', 'published', now(), now()),
  ('VTM (Venue Technical Manager)', 'VTM (Venue Technical Manager)', 'VTM (Venue Technical Manager)', 'El responsable técnico de una sede. En los Juegos, el jefe técnico de la unidad móvil cumple esta función.', 'The technical lead of a venue. At the Games, the technical chief of the OB van fulfils this role.', 'O responsável técnico de um local. Nos Jogos, o chefe técnico da unidade móvel cumpre esta função.', 'all', 'published', now(), now()),
  ('Canal Integrado', 'Integrated Channel', 'Canal Integrado', 'Canal 24/7 listo para emitir del Host Broadcaster: emisión continua todos los días de competencia, prime time en vivo de 16:00 a 22:30 y resumen diario cada noche.', 'The Host Broadcaster''s 24/7 ready-to-air channel: continuous broadcast every competition day, live prime time from 16:00 to 22:30 and a daily summary every night.', 'Canal 24/7 pronto para exibir do Host Broadcaster: transmissão contínua todos os dias de competição, horário nobre ao vivo das 16:00 às 22:30 e resumo diário todas as noites.', 'all', 'published', now(), now()),
  ('SRT (Secure Reliable Transport)', 'SRT (Secure Reliable Transport)', 'SRT (Secure Reliable Transport)', 'Protocolo de transporte de vídeo por IP. En Lima 2027, 13 señales dedicadas en H.264 a 20 Mbps, cifradas, con un Stream ID por señal.', 'IP video transport protocol. At Lima 2027, 13 dedicated signals in H.264 at 20 Mbps, encrypted, with one Stream ID per signal.', 'Protocolo de transporte de vídeo por IP. Em Lima 2027, 13 sinais dedicados em H.264 a 20 Mbps, criptografados, com um Stream ID por sinal.', 'all', 'published', now(), now()),
  ('REMI (Remote integration)', 'REMI (Remote integration)', 'REMI (Remote integration)', 'Modelo de producción en el que las cámaras están en la sede y la mezcla y las repeticiones se hacen a distancia, en una galería central.', 'Production model in which the cameras are at the venue and the mixing and replays are done remotely, in a central gallery.', 'Modelo de produção em que as câmeras estão no local e o corte e os replays são feitos remotamente, em uma galeria central.', 'all', 'published', now(), now()),
  ('Full remote', 'Full remote', 'Full remote', 'Modelo de producción en el que todas las señales de cámara viajan al IBC y la producción completa se hace allí.', 'Production model in which all camera signals travel to the IBC and the whole production is done there.', 'Modelo de produção em que todos os sinais de câmera vão para o IBC e a produção completa é feita lá.', 'all', 'published', now(), now()),
  ('Cloud MAM', 'Cloud MAM', 'Cloud MAM', 'Archivo centralizado en la nube con todas las imágenes de los Juegos, catalogado por atleta, país, disciplina y prueba. Acceso por suscripción.', 'Central cloud archive with all the footage of the Games, catalogued by athlete, country, discipline and event. Access by subscription.', 'Arquivo central na nuvem com todas as imagens dos Jogos, catalogado por atleta, país, disciplina e prova. Acesso por assinatura.', 'all', 'published', now(), now());
